    occ = [1.0 if a.get('occupancy') is None else max(0.0, a.get('occupancy')) for a in sites]
    result = 0.0
    for i in range(n):
        if radii[i] <= 0 or occ[i] <= 0:
            continue
        nearest = None
        for edge in edges:
            if edge.get('i') != i:
                continue
            j = edge.get('j')
            d = edge.get('distance_A') or 0.0
            if j is None or j < 0 or j >= n or d <= 0 or radii[j] <= 0 or occ[j] <= 0:
                continue
            reduced = d / (radii[i] + radii[j])
            if nearest is None or reduced < nearest:
                nearest = reduced
        if nearest is not None:
            result = max(result, nearest)
    return float(result)

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    edges = s.get('neighbors') or []
    n = len(sites)
    occ = [1.0 if a.get('occupancy') is None else max(0.0, a.get('occupancy')) for a in sites]
    total = 0.0
    amount = 0.0
    for i in range(n):
        if occ[i] <= 0:
            continue
        nearest = None
        for edge in edges:
            if edge.get('i') != i:
                continue
            j = edge.get('j')
            d = edge.get('distance_A') or 0.0
            if j is None or j < 0 or j >= n or d <= 0 or occ[j] <= 0:
                continue
            if nearest is None or d < nearest:
                nearest = d
        if nearest is None:
            continue
        first = 0.0
        second = 0.0
        for edge in edges:
            if edge.get('i') != i:
                continue
            j = edge.get('j')
            d = edge.get('distance_A') or 0.0
            if j is None or j < 0 or j >= n or d <= 0 or occ[j] <= 0:
                continue
            w = (nearest / d) ** 12
            first += occ[j] * w
            second += occ[j] * w * w
        if second > 0:
            total += occ[i] * first * first / second
            amount += occ[i]
    return float(total / amount) if amount > 0 else 0.0
